import { createInputController } from "../../shared/input.js";import {COAST_VISUAL_MS,PRESETS,RESULT_DWELL_MS,ROUND_WINDOW_MS,TOTAL_ROUNDS,createRun,readBest,recordRound,sampleFill,saveBest,settleFill,summarizeRun,} from "./state.js";const $ = (id) => document.getElementById(id);const [game,card,round,streakView,budget,spend,units,pump,label,clock,feedback,total,overshoots,accuracy,best,score,badge,retry,] = "game-panel result-card round-count streak-count budget spend units pump pump-label round-clock feedback total-units overshoots best-accuracy personal-best run-score new-best retry".split(" ").map($);const gauge = document.querySelector(".gauge");const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;document.body.dataset.motion = reduced ? "reduced" : "full";let run;let index;let streak;let roundAt;let holdAt;let filling;let locked;let frame;let controller;const money = (value) => `R ${value.toFixed(2)}`;function render(sample) {const progress = Math.min(100, (sample.spend / PRESETS[index][0] / 1.1) * 100);spend.textContent = money(sample.spend);units.textContent = `${sample.units.toFixed(1)} units`;gauge.style.setProperty("--progress", `${progress}%`);pump.dataset.sampleMs = Math.round(sample.elapsed);}function tick(now) {if (locked) return;const elapsed = now - roundAt;clock.textContent = `Round closes in ${(Math.max(0, ROUND_WINDOW_MS - elapsed) / 1000).toFixed(1)}s`;if (elapsed >= ROUND_WINDOW_MS) {if (filling) release(now);else finish(settleFill(index, 0, { coast: false }));return;}if (filling) {const held = now - holdAt;render(sampleFill(index, reduced ? Math.floor(held / 250) * 250 : held));}frame = requestAnimationFrame(tick);}function begin() {locked = filling = false;roundAt = performance.now();round.textContent = `${index + 1} / ${TOTAL_ROUNDS}`;streakView.textContent = streak;budget.textContent = money(PRESETS[index][0]);pump.disabled = false;pump.ariaPressed = "false";label.textContent = "Press and hold";feedback.hidden = true;render(sampleFill(index, 0));cancelAnimationFrame(frame);frame = requestAnimationFrame(tick);}function start() {if (locked || filling) return;filling = true;holdAt = performance.now();gauge.classList.add("filling");pump.ariaPressed = "true";label.textContent = "Release to stop";}function release(now = performance.now()) {if (!filling || locked) return;filling = false;locked = true;cancelAnimationFrame(frame);gauge.classList.remove("filling");gauge.classList.add("coasting");pump.disabled = true;pump.ariaPressed = "false";label.textContent = "Coasting...";const result = settleFill(index, now - holdAt);render(reduced ? result.release : result.final);setTimeout(() => {render(result.final);finish(result);}, reduced ? 120 : COAST_VISUAL_MS);}const copy = {safe: ["+ SAFE STOP", "Banked below the cap"],near: ["~ NEAR CAP", "Inside the final 5% | 1.2x"],precision: ["* PRECISION STOP", "Inside the final 2% | 1.5x"],overshoot: ["X OVER CAP", "Round lost | streak broken"],};function finish(result) {locked = true;filling = false;cancelAnimationFrame(frame);gauge.classList.remove("filling", "coasting");pump.disabled = true;pump.ariaPressed = "false";render(result.final);run = recordRound(run, result);feedback.dataset.result = result.category;feedback.innerHTML = `<strong>${copy[result.category][0]}</strong><span>${copy[result.category][1]}</span>`;feedback.hidden = false;label.textContent = "Fill settled";streak = result.category === "overshoot" ? 0 : streak + 1;streakView.textContent = streak;setTimeout(() => {index += 1;if (index === TOTAL_ROUNDS) showResults();else begin();}, RESULT_DWELL_MS);}function showResults() {controller.destroy();controller = null;const previous = readBest(localStorage);const summary = summarizeRun(run);const saved = saveBest(localStorage, summary.totalScore);total.textContent = `${summary.totalUnits.toFixed(1)} units`;overshoots.textContent = `${summary.overshoots} / ${TOTAL_ROUNDS}`;accuracy.textContent = `${summary.bestAccuracy.toFixed(1)}%`;best.textContent = `${saved.toFixed(1)} pts`;score.textContent = `Run score: ${summary.totalScore.toFixed(1)} pts`;badge.hidden = !(summary.totalScore > previous && saved > previous);game.hidden = true;card.hidden = false;card.focus();}function onInput(input) {const pointer = input.source === "pointer" && input.action === "position";const keyboard = input.source === "keyboard" && input.action === "activate";if (input.action === "reset-input" && filling) return release();if (!pointer && !keyboard) return;if (input.phase === "start") start();if (input.phase === "end" || input.phase === "cancel") release();}function startRun() {cancelAnimationFrame(frame);run = createRun();index = streak = 0;card.hidden = true;game.hidden = false;controller = createInputController(pump, { onInput });begin();pump.focus({ preventScroll: true });}retry.addEventListener("click", startRun);startRun();
